231	  enter={{
232	    'nav-forward': 'nav-forward',
233	    'nav-back': 'nav-back',
234	    default: 'none',
235	  }}
236	  exit={{
237	    'nav-forward': 'nav-forward',
238	    'nav-back': 'nav-back',
239	    default: 'none',
240	  }}
241	  default="none"
242	>
243	  {/* page content */}
244	</ViewTransition>
245	```
