259	  --slide-offset: 60px;
260	  animation:
261	    210ms ease-out 150ms both fade,
262	    400ms ease-in-out both slide;
263	}
264	
265	::view-transition-old(.nav-back) {
266	  --slide-offset: 60px;
267	  animation:
268	    150ms ease-in both fade reverse,
269	    400ms ease-in-out both slide reverse;
270	}
271	::view-transition-new(.nav-back) {
272	  --slide-offset: -60px;
273	  animation:
274	    210ms ease-out 150ms both fade,
275	    400ms ease-in-out both slide;
276	}
